void main() => runApp(const NeetPgApp());

class Mcq {
  final int id;
  final String question, explanation, subject, topic, answer;
  final List<String> options;
  Mcq(Map<String, dynamic> j)
      : id = j['id'] ?? 0,
        question = _clean(j['question'] ?? ''),
        explanation = _clean(j['explanation'] ?? ''),
        subject = _clean(j['subject'] ?? ''),
        topic = _clean(j['topic'] ?? ''),
        options = List<String>.from(j['options'] ?? []).map(_clean).toList(),
        answer = _resolveAnswer(j);
  static String _resolveAnswer(Map<String, dynamic> j) {
    final raw = _clean(j['correct_answer'] ?? '');
    if (raw.isNotEmpty) return raw;
    final opts = List<String>.from(j['options'] ?? []).map(_clean).toList();
    final counts = <String, int>{};
    for (final o in opts) { final k = o.toLowerCase(); if (k.isNotEmpty) counts[k] = (counts[k] ?? 0) + 1; }
    final dup = opts.where((o) => (counts[o.toLowerCase()] ?? 0) > 1).toSet();
    return dup.length == 1 ? dup.first : '';
  }
  static String _clean(dynamic v) => v.toString().replaceAll(RegExp(r'<[^>]*>'), '').replaceAll('&nbsp;', ' ').replaceAll('&amp;', '&').replaceAll('&lt;', '<').replaceAll('&gt;', '>').trim();
}

class NeetPgApp extends StatefulWidget {
  const NeetPgApp({super.key});
  @override State<NeetPgApp> createState() => _NeetPgAppState();
}
class _NeetPgAppState extends State<NeetPgApp> {
  bool dark = false;
  @override void initState() { super.initState(); _loadTheme(); }
  Future<void> _loadTheme() async { final p = await SharedPreferences.getInstance(); if (mounted) setState(() => dark = p.getBool('dark') ?? false); }
  Future<void> toggleTheme() async { final p = await SharedPreferences.getInstance(); await p.setBool('dark', !dark); setState(() => dark = !dark); }
  @override Widget build(BuildContext context) => MaterialApp(debugShowCheckedModeBanner: false, title: 'NEET-PG MCQ', themeMode: dark ? ThemeMode.dark : ThemeMode.light, theme: _theme(Brightness.light), darkTheme: _theme(Brightness.dark), home: HomePage(onTheme: toggleTheme, dark: dark));
  ThemeData _theme(Brightness b) => ThemeData(useMaterial3: true, brightness: b, colorSchemeSeed: const Color(0xFF4154D8), scaffoldBackgroundColor: b == Brightness.light ? const Color(0xFFF6F7FB) : const Color(0xFF101116), cardTheme: const CardThemeData(margin: EdgeInsets.zero), inputDecorationTheme: const InputDecorationTheme(border: OutlineInputBorder()));
}

class HomePage extends StatefulWidget {
  final VoidCallback onTheme; final bool dark;
  const HomePage({super.key, required this.onTheme, required this.dark});
  @override State<HomePage> createState() => _HomePageState();
}
class _HomePageState extends State<HomePage> {
  List<Mcq> all = [];
  Set<int> wrong = {}, bookmarks = {}, attempted = {}, correctIds = {};
  int dailyTarget = 30, todayDone = 0; bool loading = true; int tab = 0;
  @override void initState() { super.initState(); _load(); }
  Future<void> _load() async {
    final raw = await rootBundle.loadString('assets/mcqs.json');
    final list = (jsonDecode(raw) as List).map((e) => Mcq(e)).toList();
    final p = await SharedPreferences.getInstance();
    final day = DateTime.now().toIso8601String().substring(0,10);
    if (p.getString('day') != day) { await p.setString('day', day); await p.setInt('todayDone', 0); }
    if (!mounted) return;
    setState(() { all=list; wrong=_readSet(p,'wrong'); bookmarks=_readSet(p,'bookmarks'); attempted=_readSet(p,'attempted'); correctIds=_readSet(p,'correctIds'); dailyTarget=p.getInt('dailyTarget') ?? 30; todayDone=p.getInt('todayDone') ?? 0; loading=false; });
  }
  Set<int> _readSet(SharedPreferences p,String k)=>(p.getStringList(k)??[]).map(int.parse).toSet();
  Future<void> _save() async { final p=await SharedPreferences.getInstance(); for(final e in {'wrong':wrong,'bookmarks':bookmarks,'attempted':attempted,'correctIds':correctIds}.entries) await p.setStringList(e.key,e.value.map((x)=>'$x').toList()); await p.setInt('todayDone',todayDone); await p.setInt('dailyTarget',dailyTarget); }
