  Future<void> _customTest() async { final settings=await showModalBottomSheet<Map<String,dynamic>>(context:context,isScrollControlled:true,showDragHandle:true,builder:(c)=>const TestBuilder()); if(settings==null)return; var q=[...all]; q=q.where((x)=> (settings['subject']==null || x.subject==settings['subject']) && (settings['topic']==null || x.topic==settings['topic'])).toList()..shuffle(); final n=min(settings['count'] as int,q.length); _open(q.take(n).toList(),test:true,minutes:n,title:'Custom Test'); }
  @override Widget build(BuildContext context){ if(loading)return const Scaffold(body:Center(child:CircularProgressIndicator())); final acc=attempted.isEmpty?0:correctIds.length/attempted.length*100; return Scaffold(body: IndexedStack(index:tab,children:[_home(acc),SubjectPage(all:all,onOpen:_open),ProgressPage(total:all.length,attempted:attempted,correct:correctIds,wrong:wrong.length,all:all),SettingsPage(target:dailyTarget,onTarget:(v){setState(()=>dailyTarget=v);_save();})]),bottomNavigationBar:NavigationBar(selectedIndex:tab,onDestinationSelected:(v)=>setState(()=>tab=v),destinations:const [NavigationDestination(icon:Icon(Icons.home_outlined),selectedIcon:Icon(Icons.home),label:'Home'),NavigationDestination(icon:Icon(Icons.menu_book_outlined),selectedIcon:Icon(Icons.menu_book),label:'Subjects'),NavigationDestination(icon:Icon(Icons.insights_outlined),selectedIcon:Icon(Icons.insights),label:'Progress'),NavigationDestination(icon:Icon(Icons.settings_outlined),selectedIcon:Icon(Icons.settings),label:'Settings')])); }
  Widget _home(double acc)=>CustomScrollView(slivers:[SliverAppBar(pinned:true,backgroundColor:Theme.of(context).scaffoldBackgroundColor,title:const Text('NEET-PG',style:TextStyle(fontWeight:FontWeight.w900)),actions:[IconButton(icon:const Icon(Icons.search),onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>SearchPage(all:all,onOpen:_open)))),IconButton(icon:Icon(widget.dark?Icons.light_mode:Icons.dark_mode),onPressed:widget.onTheme)]),SliverPadding(padding:const EdgeInsets.fromLTRB(16,8,16,28),sliver:SliverList(delegate:SliverChildListDelegate([_hero(acc),const SizedBox(height:16),_daily(),const SizedBox(height:20),_section('Quick Practice'),_action('Practice All','Random • up to 100 questions',Icons.play_circle_fill,(){final q=[...all]..shuffle();_open(q.take(min(100,q.length)).toList(),title:'Practice');}),_action('Custom Test','25 / 50 / 100 • filters + timer',Icons.timer,_customTest),_action('Wrong Questions','${wrong.length} questions need revision',Icons.error_outline,()=>_open(all.where((x)=>wrong.contains(x.id)).toList(),title:'Wrong Questions')),_action('Bookmarks','${bookmarks.length} saved questions',Icons.bookmark,()=>_open(all.where((x)=>bookmarks.contains(x.id)).toList(),title:'Bookmarks')),const SizedBox(height:20),_section('High-Yield Tools'),_action('Search MCQs','Find by question, topic or explanation',Icons.manage_search,()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>SearchPage(all:all,onOpen:_open)))),_action('Progress Analytics','Accuracy, attempted, wrong & subject performance',Icons.analytics,()=>setState(()=>tab=2))])))]);
